import { expect, test, uniqueName } from "../../fixtures";

// Local calendar date `days` from today, as YYYY-MM-DD (the format the extractor parses).
function isoDateFromToday(days: number): string {
  const d = new Date();
  d.setDate(d.getDate() + days);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

const FLAG = "insurance_expiring_soon";

test.describe("insurance expiry flag", () => {
  const examples: Array<{ days: number; include: boolean }> = [
    { days: 0, include: true },
    { days: 30, include: true },
    { days: 31, include: false },
  ];

  for (const { days, include } of examples) {
    test(`a certificate expiring in ${days} days ${include ? "includes" : "does not include"} the expiring-soon flag`, { tag: "@REV-08" }, async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const vendorRes = await member.post("/api/vendors", {
        data: {
          name: uniqueName("Expiry Flag"),
          category: "services",
          contact_email: `ops-${Date.now().toString(36)}-${days}@example.com`,
        },
      });
      expect(vendorRes.status(), await vendorRes.text()).toBe(201);
      const vendor = await vendorRes.json();

      const body = `Insurer: Harbor Mutual\nPolicy Number: HM-${days}\nCoverage Amount: $2,000,000\nExpiry Date: ${isoDateFromToday(days)}\n`;
      const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: { name: "insurance.txt", mimeType: "text/plain", buffer: Buffer.from(body) },
        },
      });
      expect(upload.status(), await upload.text()).toBe(201);
      const doc = await upload.json();

      // Extraction runs in the background; wait until the document is extracted.
      await expect
        .poll(async () => {
          const r = await member.get(`/api/documents/${doc.id}`);
          return (await r.json()).status;
        })
        .toBe("extracted");

      // Act
      const res = await member.get(`/api/vendors/${vendor.id}`);

      // Assert
      expect(res.status(), await res.text()).toBe(200);
      const flags: string[] = (await res.json()).flags;
      if (include) {
        expect(flags, `flags: ${flags.join(", ")}`).toContain(FLAG);
      } else {
        expect(flags, `flags: ${flags.join(", ")}`).not.toContain(FLAG);
      }
    });
  }
});
